// The now playing bar's text split (NowPlayingBar.x placeText): a page's "title • artists" line, or its title
// alone, parted into the two lines the redesign draws, with the track metadata the player reports deciding
// where a title that holds " • " itself ends. NowPlayingBar.x is generated by Logos and included here so its
// statics are reachable; the player state, the view tree of Spotify's page and the stubs it links against are
// doubles. A failed check exits 1 with its name.
#import <UIKit/UIKit.h>
#import "../harness-fail.h"
#import "Shared/Player/PlayerState.h"

#pragma mark - the player's state, a double

@interface SPTPlayerTrack ()
@property (nonatomic, readwrite) NSString *trackTitle;
@property (nonatomic, readwrite) NSString *artistName;
@end
// Every read of a title is counted: a scan of the player's tracks reads one per track, so the count tells scans apart.
static NSUInteger sg_titleReads;

@implementation SPTPlayerTrack {
    NSString *_trackTitle;
}
- (NSString *)trackTitle {
    sg_titleReads++;
    return _trackTitle;
}
- (void)setTrackTitle:(NSString *)title {
    _trackTitle = title;
}
@end

@interface SPTPlayerState ()
@property (nonatomic, readwrite) SPTPlayerTrack *track;
@property (nonatomic, readwrite) NSArray *future;
@property (nonatomic, readwrite) NSArray *reverse;
@end
@implementation SPTPlayerState
@end

static SPTPlayerState *sg_state;
SPTPlayerState *SGPlayerState(void) { return sg_state; }

// The player the Next button asks, a double that counts the skips it is asked for.
@interface SGHarnessPlayer : NSObject
@property (nonatomic) NSUInteger skips;
@end
@implementation SGHarnessPlayer
- (id)skipToNextTrackWithOptions:(id)options {
    self.skips++;
    return nil;
}
@end
static SGHarnessPlayer *sg_player;
id SGPlayer(void) { return sg_player; }

#include "NowPlayingBar.gen.m"

#pragma mark - Spotify's page, a double

static SPTPlayerTrack *makeTrack(NSString *title, NSString *artist) {
    SPTPlayerTrack *t = [SPTPlayerTrack new];
    t.trackTitle = title;
    t.artistName = artist;
    return t;
}

// A marquee as Spotify nests it: a view named Encore.MarqueeLabel holding the label that has the text.
static UIView *addMarquee(UIView *unit, NSString *text, BOOL hidden) {
    UIView *view = [[UIView alloc] initWithFrame:CGRectMake(0, 0, 200, 20)];
    view.accessibilityIdentifier = @"Encore.MarqueeLabel";
    view.hidden = hidden;
    UILabel *label = [[UILabel alloc] initWithFrame:view.bounds];
    label.text = text;
    [view addSubview:label];
    [unit addSubview:view];
    return view;
}

// `device`: the page with a device line, whose first marquee is "title • artists" and a later hidden one the
// artists alone (empty when `hiddenArtists` is nil). Without: the title, then the artists in sight.
static UIView *makePage(NSString *line, NSString *hiddenArtists, BOOL device, NSString *shownArtists) {
    UIView *page = [[UIView alloc] initWithFrame:CGRectMake(0, 0, 300, 56)];
    page.accessibilityIdentifier = kPageId;
    UIView *unit = [[UIView alloc] initWithFrame:page.bounds];
    unit.accessibilityIdentifier = kUnitId;
    [page addSubview:unit];
    addMarquee(unit, line, NO);
    if (device) addMarquee(unit, hiddenArtists ?: @"", YES);
    else addMarquee(unit, shownArtists, NO);
    return page;
}

static NSUInteger sg_checks;

static void expect(NSString *name, UIView *page, NSString *title, NSString *artists) {
    placeText(page);
    SGRBarText *text = objc_getAssociatedObject(page, &kTextKey);
    HARNESS_CHECK(text != nil);
    NSString *gotArtists = text.artists.text;
    if (![text.title.text isEqualToString:title] || ![gotArtists isEqualToString:artists]) {
        HARNESS_FAIL(@"%@: title \"%@\" artists \"%@\", wanted \"%@\" \"%@\"", name, text.title.text, gotArtists, title, artists);
    }
    sg_checks++;
}

// The text size is the app's (stubs.m) and the window's traits, which is how UIKit tells a view the size changed.
extern UIContentSizeCategory sg_harnessTextSize;

static void setTextSize(UIWindow *window, UIContentSizeCategory category) {
    sg_harnessTextSize = category;
    window.traitOverrides.preferredContentSizeCategory = category;
    // Hand the new traits down now rather than whenever the window next lays out: a slow machine may not in 0.1 s.
    [window updateTraitsIfNeeded];
    [window layoutIfNeeded];
    [NSRunLoop.mainRunLoop runUntilDate:[NSDate dateWithTimeIntervalSinceNow:0.1]];
}

static SGRBarText *barIn(UIView *host) {
    UIView *page = makePage(@"Stay High • Juice WRLD", @"", YES, nil);
    [host addSubview:page];
    placeText(page);
    return objc_getAssociatedObject(page, &kTextKey);
}

// Both fonts and both frames, as the bar draws them.
static NSString *textLook(SGRBarText *text) {
    return [NSString stringWithFormat:@"title %.1fpt %@, artists %.1fpt %@", text.title.font.pointSize,
            NSStringFromCGRect(text.title.frame), text.artists.font.pointSize, NSStringFromCGRect(text.artists.frame)];
}

// A bar kept across text sizes looks as one made at that size.
static void checkTextSize(void) {
    UIWindow *window = [(id)UIApplication.sharedApplication.delegate window];
    UIView *host = window.rootViewController.view;
    setTextSize(window, UIContentSizeCategorySmall);
    SGRBarText *kept = barIn(host);
    NSString *small = textLook(kept);
    NSString *large = nil;
    for (UIContentSizeCategory category in @[UIContentSizeCategoryLarge, UIContentSizeCategorySmall]) {
        setTextSize(window, category);
        NSString *fresh = textLook(barIn(host)), *now = textLook(kept);
        if (![now isEqualToString:fresh]) HARNESS_FAIL(@"text size %@: a kept bar draws %@, a new one %@", category, now, fresh);
        if (category == UIContentSizeCategoryLarge) large = now;
        sg_checks++;
    }
    if ([small isEqualToString:large]) HARNESS_FAIL(@"same %@ / %@", small, large);
    HARNESS_CHECK([textLook(kept) isEqualToString:small]);
}

#pragma mark - the artist under the title in the minimized row

static UIView *sg_rowHost;

// A page of `height` placed in the bar's row (the minimized tab bar's) or on the full card, the text it draws.
static SGRBarText *placeAt(UIView *page, CGFloat height, BOOL inRow) {
    if (!sg_rowHost) sg_rowHost = [UIView new];
    sg_inline = inRow ? sg_rowHost : nil;
    page.frame = CGRectMake(0, 0, 300, height);
    placeText(page);
    return objc_getAssociatedObject(page, &kTextKey);
}

static CGFloat lineHeights(SGRBarText *text, CGFloat *artistsHeight) {
    *artistsHeight = ceil(text.artists.font.lineHeight);
    return ceil(text.title.font.lineHeight);
}

// Title only: the artists faded out and the title alone centered in the bar.
static void expectTitleOnly(NSString *name, SGRBarText *text, CGFloat height) {
    CGFloat a, t = lineHeights(text, &a);
    if (text.artists.alpha != 0 || text.title.frame.origin.y != round((height - t) / 2) || text.title.frame.size.height != t) {
        HARNESS_FAIL(@"%@: wanted the title alone, got title %@ artists %@ alpha %.0f", name, NSStringFromCGRect(text.title.frame),
                     NSStringFromCGRect(text.artists.frame), text.artists.alpha);
    }
    sg_checks++;
}

// Two lines, the artists `gap` under the title's frame, the pair centered in the bar.
static void expectTwoLines(NSString *name, SGRBarText *text, CGFloat height, CGFloat gap) {
    CGFloat a, t = lineHeights(text, &a);
    CGFloat top = round((height - t - a - gap) / 2);
    if (text.artists.alpha != 1 || text.title.frame.origin.y != top || text.artists.frame.origin.y != top + t + gap
        || text.artists.frame.size.height != a) {
        HARNESS_FAIL(@"%@: wanted two lines %.0fpt apart from y %.0f, got title %@ artists %@ alpha %.0f", name, gap, top,
                     NSStringFromCGRect(text.title.frame), NSStringFromCGRect(text.artists.frame), text.artists.alpha);
    }
    sg_checks++;
}

static UIView *plainPage(void) { return makePage(@"Stay High", nil, NO, @"Juice WRLD"); }

static void checkInlineArtist(void) {
    UIWindow *window = [(id)UIApplication.sharedApplication.delegate window];
    UIView *host = window.rootViewController.view;
    setTextSize(window, UIContentSizeCategoryLarge);
    sg_state = nil;
    CGFloat a, t = lineHeights(placeAt(plainPage(), 56, YES), &a);
    CGFloat fits = t + a + 6;

    SGSetEnabled(SGRKeyBarInlineArtist, NO);
    expectTitleOnly(@"off, in the row", placeAt(plainPage(), 56, YES), 56);

    SGSetEnabled(SGRKeyBarInlineArtist, YES);
    expectTwoLines(@"on, roomy bar", placeAt(plainPage(), 56, YES), 56, 1);
    expectTwoLines(@"on, bar exactly as high as both lines and 6pt", placeAt(plainPage(), fits, YES), fits, 1);
    expectTitleOnly(@"on, bar 1pt too low", placeAt(plainPage(), fits - 1, YES), fits - 1);

    // A title with the bullet: the split is the same, and so are the two lines.
    sg_state = [SPTPlayerState new];
    sg_state.track = makeTrack(@"Rock • Roll", @"The Band");
    SGRBarText *dotted = placeAt(makePage(@"Rock • Roll • The Band", @"", YES, nil), 56, YES);
    HARNESS_CHECK([dotted.title.text isEqualToString:@"Rock • Roll"] && [dotted.artists.text isEqualToString:@"The Band"]);
    expectTwoLines(@"on, title with a bullet", dotted, 56, 1);
    sg_state = nil;

    // No artist: the title alone, and two lines once the artist arrives.
    UIView *late = makePage(@"Stay High", nil, NO, nil);
    expectTitleOnly(@"on, no artist", placeAt(late, 56, YES), 56);
    UIView *unit = late.subviews.firstObject;
    ((UILabel *)unit.subviews[1].subviews.firstObject).text = @"Juice WRLD";
    expectTwoLines(@"on, artist comes in late", placeAt(late, 56, YES), 56, 1);

    // The switch flipped on a bar already drawn follows on the next placement.
    UIView *kept = plainPage();
    SGSetEnabled(SGRKeyBarInlineArtist, NO);
    expectTitleOnly(@"live, switched off", placeAt(kept, 56, YES), 56);
    SGSetEnabled(SGRKeyBarInlineArtist, YES);
    expectTwoLines(@"live, switched on", placeAt(kept, 56, YES), 56, 1);

    // The text size changes what fits: a bar just high enough at Small is too low at Large.
    setTextSize(window, UIContentSizeCategorySmall);
    UIView *small = plainPage();
    [host addSubview:small];
    SGRBarText *keptText = placeAt(small, 1, YES);
    CGFloat smallArtists, smallTitle = lineHeights(keptText, &smallArtists);
    CGFloat smallFits = smallTitle + smallArtists + 6;
    keptText = placeAt(small, smallFits, YES);
    expectTwoLines(@"small text, bar just high enough", keptText, smallFits, 1);
    setTextSize(window, UIContentSizeCategoryLarge);
    [keptText layoutIfNeeded];
    HARNESS_CHECK(fits > smallFits);
    expectTitleOnly(@"large text, same bar", keptText, smallFits);
    [small removeFromSuperview];

    // The full card is the two lines it always was, however low, and whatever the switch says.
    for (NSNumber *on in @[@NO, @YES]) {
        SGSetEnabled(SGRKeyBarInlineArtist, on.boolValue);
        for (NSNumber *height in @[@56, @(fits - 1)]) {
            SGRBarText *full = placeAt(plainPage(), height.doubleValue, NO);
            expectTwoLines(@"full card", full, height.doubleValue, -2);
        }
    }
    SGSetEnabled(SGRKeyBarInlineArtist, NO);
    sg_inline = nil;
}

#pragma mark - the Next button and the artwork's shape

// A setting as a fresh install has it: not stored at all.
static void unset(NSString *key) {
    [NSUserDefaults.standardUserDefaults removeObjectForKey:key];
    SGPrefsChanged();
}

// Spotify's button stack as 9.1.90 lays it out: the device, add and play buttons, each in an item of its own.
static UIView *buttonItem(UIStackView *stack, NSString *identifier) {
    UIView *item = [[UIView alloc] initWithFrame:CGRectMake(0, 0, 44, 40)];
    UIView *button = [[UIButton alloc] initWithFrame:item.bounds];
    button.accessibilityIdentifier = identifier;
    [item addSubview:button];
    [stack addArrangedSubview:item];
    return item;
}

static SGRBarNextButton *nextIn(UIStackView *stack) {
    SGRBarNextButton *found = nil;
    for (UIView *item in stack.arrangedSubviews) {
        if (![item isKindOfClass:SGRBarNextButton.class]) continue;
        if (found) HARNESS_FAIL(@"next button: two of them in the row");
        found = (SGRBarNextButton *)item;
    }
    return found;
}

// Off unless set; on, one button after Spotify's buttons, last in the row and as large as play's item, Spotify's
// buttons left as they were, that asks the player for the next track, hidden in the minimized row with the add button
// and back with the full card; off again, gone from the row.
static void checkNextButton(void) {
    UIView *bar = [[UIView alloc] initWithFrame:CGRectMake(0, 0, 360, 56)];
    UIStackView *stack = [[UIStackView alloc] initWithFrame:CGRectMake(172, 0, 132, 40)];
    UIStackView *row = [[UIStackView alloc] initWithArrangedSubviews:@[[[UIView alloc] initWithFrame:CGRectMake(0, 0, 168, 40)], stack]];
    row.frame = CGRectMake(48, 8, 304, 40);
    [bar addSubview:row];
    buttonItem(stack, @"Components.ConnectButtonOutputSwitcher");
    UIView *add = buttonItem(stack, @"Components.UI.AddToButton");
    UIView *play = buttonItem(stack, kPlayId);
    NSArray<UIView *> *spotify = stack.arrangedSubviews;

    unset(SGRKeyBarNextButton);
    placeNextButton(bar);
    if (nextIn(row)) HARNESS_FAIL(@"next button: shown with the switch unset");
    sg_checks++;

    SGSetEnabled(SGRKeyBarNextButton, YES);
    placeNextButton(bar);
    placeNextButton(bar);
    SGRBarNextButton *next = nextIn(row);
    if (!next || row.arrangedSubviews.lastObject != next || next.hidden || ![stack.arrangedSubviews isEqualToArray:spotify]) {
        HARNESS_FAIL(@"next button: wanted it last in the row after Spotify's buttons %@, got %@ in %@, buttons %@",
                     spotify, next, row.arrangedSubviews, stack.arrangedSubviews);
    }
    sg_checks++;

    // Laid out at play's 44x40 in the 40 pt row, it still takes every touch of a 44x44 pt square about its middle
    // through the hit test of the bar's page.
    UIView *host = [(id)UIApplication.sharedApplication.delegate window].rootViewController.view;
    [host addSubview:bar];
    [bar layoutIfNeeded];
    CGPoint mid = [next convertPoint:CGPointMake(CGRectGetMidX(next.bounds), CGRectGetMidY(next.bounds)) toView:bar];
    CGFloat reach = 44.0 / 2 - 0.5;
    for (int corner = 0; corner < 4; corner++) {
        CGPoint p = CGPointMake(mid.x + (corner & 1 ? reach : -reach), mid.y + (corner & 2 ? reach : -reach));
        if (nextButtonHit(bar, p, nil) != next) {
            HARNESS_FAIL(@"next button: %@ outside its touch target (laid out at %@ in a row %.0f pt high); wanted 44x44 pt",
                         NSStringFromCGPoint(p), NSStringFromCGRect([next convertRect:next.bounds toView:bar]), row.bounds.size.height);
        }
    }
    sg_checks++;

    sg_player = [SGHarnessPlayer new];
    [next sendActionsForControlEvents:UIControlEventTouchUpInside];
    if (sg_player.skips != 1) HARNESS_FAIL(@"next button: a tap asked for %lu skips", (unsigned long)sg_player.skips);
    sg_player = nil;
    sg_checks++;

    tuckExtras(bar, YES);
    if (!next.hidden || !add.hidden) HARNESS_FAIL(@"next button: in the row next hidden %d, add hidden %d", next.hidden, add.hidden);
    tuckExtras(bar, NO);
    if (next.hidden || add.hidden) HARNESS_FAIL(@"next button: back on the full card next hidden %d, add hidden %d", next.hidden, add.hidden);
    sg_checks++;

    SGSetEnabled(SGRKeyBarNextButton, NO);
    placeNextButton(bar);
    if (nextIn(row) || next.superview) HARNESS_FAIL(@"next button: still there with the switch off");
    sg_checks++;

    // On again, and then Spotify's bar no longer holds play in its button stack: the Next placed before goes.
    SGSetEnabled(SGRKeyBarNextButton, YES);
    placeNextButton(bar);
    next = nextIn(row);
    HARNESS_CHECK(next != nil);
    [stack removeArrangedSubview:play];
    [play removeFromSuperview];
    [bar addSubview:play];
    placeNextButton(bar);
    if (next.superview || nextButtonHit(bar, mid, nil)) HARNESS_FAIL(@"next button: still in %@ after play left its stack", next.superview);
    sg_checks++;
    [bar removeFromSuperview];
    unset(SGRKeyBarNextButton);
}

// The cover's two views of Spotify's, the outer one plain and the image's own with Spotify's 4pt corners, as rounded
// for each shape: a circle unless set, 8pt corners for Rounded square, and back, on the same card as the choice changes.
static void checkArtworkShape(void) {
    UIView *card = [[UIView alloc] initWithFrame:CGRectMake(0, 0, 360, 56)];
    UIView *outer = [[UIView alloc] initWithFrame:CGRectMake(8, 8, 40, 40)];
    UIView *image = [[UIView alloc] initWithFrame:outer.bounds];
    image.layer.cornerRadius = 4;
    [outer addSubview:image];
    [card addSubview:outer];
    sg_cardArtwork = nil;
    struct { NSInteger shape; BOOL stored; CGFloat radius; } steps[] = {
        {0, NO, 20}, {SGRBarArtworkShapeRoundedSquare, YES, 8}, {SGRBarArtworkShapeCircle, YES, 20},
    };
    for (size_t i = 0; i < sizeof steps / sizeof *steps; i++) {
        if (steps[i].stored) SGSetInt(SGRKeyBarArtworkShape, steps[i].shape);
        else unset(SGRKeyBarArtworkShape);
        restyleCardContent(card);
        CGFloat want = steps[i].radius;
        if (outer.layer.cornerRadius != want || image.layer.cornerRadius != want || sg_cardArtwork != outer) {
            HARNESS_FAIL(@"artwork shape %ld (stored %d): wanted %.0fpt corners on the cover, got outer %.1f, image %.1f, artwork %@",
                         (long)steps[i].shape, steps[i].stored, want, outer.layer.cornerRadius, image.layer.cornerRadius, sg_cardArtwork);
        }
        sg_checks++;
    }
    unset(SGRKeyBarArtworkShape);
}

static void run(void) {
    SPTPlayerTrack *plain = makeTrack(@"Stay High", @"Juice WRLD"), *dotted = makeTrack(@"Rock • Roll", @"The Band");
    SPTPlayerTrack *shorter = makeTrack(@"Rock", @"Roll Crew");
    sg_state = [SPTPlayerState new];
    sg_state.track = dotted;
    sg_state.future = @[plain, shorter];
    sg_state.reverse = @[makeTrack(@"Back • Again", @"Looper")];

    // A title without the bullet, either layout: what the page always did.
    expect(@"plain, device line", makePage(@"Stay High • Juice WRLD", @"", YES, nil), @"Stay High", @"Juice WRLD");
    expect(@"plain, device line and artists", makePage(@"Stay High • Juice WRLD", @"Juice WRLD", YES, nil), @"Stay High", @"Juice WRLD");
    expect(@"plain, no device line", makePage(@"Stay High", nil, NO, @"Juice WRLD"), @"Stay High", @"Juice WRLD");

    // A title with the bullet, the current track.
    expect(@"dotted, device line, hidden artists empty", makePage(@"Rock • Roll • The Band", @"", YES, nil), @"Rock • Roll", @"The Band");
    expect(@"dotted, device line, hidden artists", makePage(@"Rock • Roll • The Band", @"The Band", YES, nil), @"Rock • Roll", @"The Band");
    expect(@"dotted, no device line", makePage(@"Rock • Roll", nil, NO, @"The Band"), @"Rock • Roll", @"The Band");

    // The page of a neighbor in the pager, not the current track: a track to come and one played.
    expect(@"played neighbor", makePage(@"Back • Again • Looper", @"", YES, nil), @"Back • Again", @"Looper");
    expect(@"next neighbor", makePage(@"Rock • Roll Crew", @"", YES, nil), @"Rock", @"Roll Crew");
    expect(@"next neighbor, plain", makePage(@"Stay High • Juice WRLD", @"", YES, nil), @"Stay High", @"Juice WRLD");

    // A short title followed by its artist is the head of a neighbor's longer one: the longer title wins.
    sg_state = [SPTPlayerState new];
    sg_state.track = makeTrack(@"Rock", @"Roll");
    sg_state.future = @[makeTrack(@"Rock • Roll", @"The Band")];
    expect(@"collision, neighbor, hidden artists", makePage(@"Rock • Roll • The Band", @"The Band", YES, nil), @"Rock • Roll", @"The Band");
    expect(@"collision, neighbor, hidden artists empty", makePage(@"Rock • Roll • The Band", @"", YES, nil), @"Rock • Roll", @"The Band");
    expect(@"collision, current", makePage(@"Rock", nil, NO, @"Roll"), @"Rock", @"Roll");

    // The same page laid out again, with the same state and line, is not scanned again; a new line or a new state
    // is, and its answer follows.
    sg_state = [SPTPlayerState new];
    sg_state.track = makeTrack(@"Rock • Roll", @"The Band");
    sg_state.future = @[makeTrack(@"Stay High", @"Juice WRLD")];
    UIView *again = makePage(@"Rock • Roll • The Band", @"", YES, nil);
    sg_titleReads = 0;
    expect(@"cache, first layout", again, @"Rock • Roll", @"The Band");
    NSUInteger scan = sg_titleReads;
    HARNESS_CHECK(scan > 0);
    expect(@"cache, same layout again", again, @"Rock • Roll", @"The Band");
    expect(@"cache, same line on another page", makePage(@"Rock • Roll • The Band", @"The Band", YES, nil), @"Rock • Roll", @"The Band");
    if (sg_titleReads != scan) HARNESS_FAIL(@"cache: an unchanged line and state were scanned again (%lu reads, %lu for one scan)", (unsigned long)sg_titleReads, (unsigned long)scan);
    expect(@"cache, new line", makePage(@"Stay High • Juice WRLD", @"", YES, nil), @"Stay High", @"Juice WRLD");
    if (sg_titleReads == scan) HARNESS_FAIL(@"cache: a new line was not scanned");
    scan = sg_titleReads;
    SPTPlayerState *next = [SPTPlayerState new];
    next.track = makeTrack(@"Stay High • Juice WRLD", @"Someone");
    sg_state = next;
    expect(@"cache, new state", makePage(@"Stay High • Juice WRLD", nil, NO, @"Someone"), @"Stay High • Juice WRLD", @"Someone");
    HARNESS_CHECK(sg_titleReads > scan);

    // Nothing the player knows: today's reading, the first bullet parts the title.
    sg_state = [SPTPlayerState new];
    expect(@"unknown, device line", makePage(@"Rock • Roll • The Band", @"", YES, nil), @"Rock", @"Roll • The Band");
    expect(@"unknown, no bullet", makePage(@"Unknown Song", nil, NO, @"Somebody"), @"Unknown Song", @"Somebody");
    sg_state = nil;
    expect(@"no state", makePage(@"Stay High • Juice WRLD", @"", YES, nil), @"Stay High", @"Juice WRLD");

    checkInlineArtist();
    checkTextSize();
    checkNextButton();
    checkArtworkShape();

    printf("[harness] now-playing-bar: %lu checks passed\n", (unsigned long)sg_checks);
    fflush(stdout);
    exit(0);
}

@interface NowPlayingBarApp : UIResponder <UIApplicationDelegate>
@property (nonatomic, strong) UIWindow *window;
@end
@implementation NowPlayingBarApp
- (BOOL)application:(UIApplication *)application didFinishLaunchingWithOptions:(NSDictionary *)options {
    self.window = [[UIWindow alloc] initWithFrame:CGRectMake(0, 0, 390, 844)];
    self.window.rootViewController = [UIViewController new];
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(0.2 * NSEC_PER_SEC)), dispatch_get_main_queue(), ^{ run(); });
    return YES;
}
@end

int main(int argc, char *argv[]) {
    @autoreleasepool {
        return UIApplicationMain(argc, argv, nil, NSStringFromClass(NowPlayingBarApp.class));
    }
}
